const canon=v=>normalize(String(v)).replaceAll(' ','_');
const db=new DatabaseSync(dbPath,{readOnly:dry});
try{
 const columns=db.prepare('PRAGMA table_info(knowledge_relations)').all().map(x=>x.name);
 for(const col of ['id','subject','predicate','object','confidence','source_type','evidence_count'])if(!columns.includes(col))throw Error('Coluna ausente: '+col);
 const find=db.prepare('SELECT 1 FROM knowledge_relations WHERE subject=? AND predicate=? AND object=? LIMIT 1');
 const insert=db.prepare('INSERT INTO knowledge_relations (id,subject,predicate,object,confidence,source_type,evidence_count) VALUES (?,?,?,?,?,?,?)');
 const seen=new Set(),pending=[];
 for(const row of FACTS){
   const triple=row.map(canon);const [s,p,o]=triple;
   if(!s||!p||!o||s.length>100||p.length>100||o.length>100)throw Error('Dado invalido: '+JSON.stringify(row));
   const key=JSON.stringify(triple);if(seen.has(key))continue;seen.add(key);
   if(!find.get(...triple))pending.push(triple);
 }
 console.log(`Lote 013: ${FACTS.length} relações; ${seen.size} únicas; ${pending.length} novas; ${seen.size-pending.length} existentes.`);
 console.log('Categorias: 15+ animais em anfibios, mamiferos, insetos, herbivoros, peixes, moluscos, vertebrados, invertebrados, marinhos e agua doce.');
 if(dry)console.log('SIMULACAO: nenhuma alteracao no SQLite.');
 else{db.exec('BEGIN IMMEDIATE');try{for(const row of pending)insert.run(randomUUID(),...row,null,'imported',1);db.exec('COMMIT');console.log('IMPORTACAO CONCLUIDA: '+pending.length+' relações novas, pesos preservados.');}catch(e){db.exec('ROLLBACK');throw e}}
}finally{db.close()}
